def num_of_subarrays(arr, k, threshold):
    n = len(arr)
    count = 0
    for start in range(n - k + 1):
        window_sum = sum(arr[start:start + k])                          # re-add every element of this window from scratch
        if window_sum / k >= threshold:
            count += 1
    return count


